package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen1Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        writer = new StringWriter();
    }



    @Test
    public void testTranslate_DecimalSuccess() throws IOException {
        // &#123; -> {
        // index 0: & (0), # (1), 1 (2), 2 (3), 3 (4), ; (5)
        // start = 2, end = 5. isHex = false.
        // return 2 + (5-2) + 0 + 1 = 6
        String input = "&#123;";
        int result = unescaper.translate(input, 0, writer);
        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }












}

